import{_ as t,o,c as a,ag as s}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/sheets/lakehouse-connection.png",p=JSON.parse('{"title":"Read lakehouse tables","description":"Read an Apache Iceberg or Delta Lake table from object storage into a read-only tab, and look at earlier versions with time travel.","frontmatter":{"title":"Read lakehouse tables","description":"Read an Apache Iceberg or Delta Lake table from object storage into a read-only tab, and look at earlier versions with time travel.","type":"how-to"},"headers":[],"relativePath":"sheets/lakehouse.md","filePath":"sheets/lakehouse.md"}'),r={name:"sheets/lakehouse.md"};function l(i,e,d,c,h,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="read-lakehouse-tables" tabindex="-1">Read lakehouse tables <a class="header-anchor" href="#read-lakehouse-tables" aria-label="Permalink to &quot;Read lakehouse tables&quot;">​</a></h1><p>Read an Apache Iceberg or Delta Lake table from object storage into a read-only tab, and look at earlier versions with time travel.</p><p>A lakehouse tab has no query box. It shows the whole table its connection points at, as soon as you open it.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Connections are shared with the workspace. Every member reads with the credentials you save, so use read-only storage credentials.</li><li>A saved lakehouse connection can&#39;t be edited or deleted in the app.</li><li>Reads stop at 10,000 rows, and a read stops after 30 seconds by default.</li></ul></div><h2 id="add-a-lakehouse-tab" tabindex="-1">Add a lakehouse tab <a class="header-anchor" href="#add-a-lakehouse-tab" aria-label="Permalink to &quot;Add a lakehouse tab&quot;">​</a></h2><ol><li>Open the sheet. At the end of the tab bar, click the arrow next to <strong>+</strong> (<strong>More tab types</strong>) and select <strong>Connect lakehouse table…</strong>.</li><li>In <strong>Select lakehouse</strong>, click a connection and click <strong>Select</strong>, or double-click it.</li><li>To add a connection instead, click <strong>New connection</strong> and follow <a href="#set-up-a-connection">Set up a connection</a>.</li></ol><p>A new tab named after the connection opens, marked with a warehouse icon. The status line reads <strong>Loading rows…</strong>, then something like <code>1204 rows in 812ms</code>.</p><h2 id="set-up-a-connection" tabindex="-1">Set up a connection <a class="header-anchor" href="#set-up-a-connection" aria-label="Permalink to &quot;Set up a connection&quot;">​</a></h2><ol><li>In <strong>New lakehouse connection</strong>, enter a <strong>Name</strong>.</li><li>Choose the <strong>Table format</strong>: <strong>Apache Iceberg</strong> or <strong>Delta Lake</strong>.</li><li>Choose the <strong>Storage</strong> and fill in its fields. See <a href="#storage-options">Storage options</a>.</li><li>Enter the table path. For Iceberg it&#39;s labeled <strong>Iceberg metadata file (.metadata.json)</strong>; for Delta, <strong>Delta table root</strong>. See <a href="#write-the-table-path">Write the table path</a>.</li><li>Click <strong>Test connection</strong>. A message says <code>Connected</code>, or why it couldn&#39;t connect.</li><li>Click <strong>Save</strong>.</li></ol><p>The new tab opens and reads the table.</p><p><img src="'+n+'" alt="New lakehouse connection dialog set to Apache Iceberg on S3-compatible storage"></p><h3 id="storage-options" tabindex="-1">Storage options <a class="header-anchor" href="#storage-options" aria-label="Permalink to &quot;Storage options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Storage</th><th>Fields</th></tr></thead><tbody><tr><td><strong>Amazon S3</strong></td><td><strong>Bucket</strong>, <strong>Region</strong> (default <code>us-east-1</code>), <strong>Access key</strong>, <strong>Secret key</strong>, <strong>Session token (optional)</strong></td></tr><tr><td><strong>S3-compatible</strong></td><td><strong>Bucket</strong>, <strong>Region</strong>, <strong>Endpoint</strong> (an <code>http://</code> or <code>https://</code> URL with no path), <strong>Access key</strong>, <strong>Secret key</strong>, <strong>Session token (optional)</strong></td></tr><tr><td><strong>Google Cloud Storage</strong></td><td><strong>Bucket</strong>, <strong>Access key</strong>, <strong>Secret key</strong>. Use GCS interoperability (HMAC) keys</td></tr><tr><td><strong>Azure Blob / ADLS</strong></td><td><strong>Container</strong>, <strong>Custom endpoint (optional)</strong>, and either <strong>Connection string (optional)</strong> alone, or <strong>Account name</strong> with <strong>Account key</strong> or <strong>SAS token (optional)</strong></td></tr><tr><td><strong>Local filesystem (server-configured)</strong></td><td>The table path only, as an absolute server path</td></tr></tbody></table><p>Amazon S3, S3-compatible, and Google Cloud Storage need both an access key and a secret key. Until both are filled in, <strong>Save</strong> stays unavailable and the key fields show an error.</p><div class="info custom-block"><p class="custom-block-title">Server settings</p><p><strong>Local filesystem</strong> works only when the server operator turns it on, inside one allowed folder. Custom endpoints must also be on the operator&#39;s allowlist. See <a href="/docs/developers/self-hosting/optional-features.html">Optional features</a>.</p></div><h3 id="write-the-table-path" tabindex="-1">Write the table path <a class="header-anchor" href="#write-the-table-path" aria-label="Permalink to &quot;Write the table path&quot;">​</a></h3><ul><li><strong>Iceberg</strong>: point at a metadata file. The path must end in <code>.metadata.json</code>.</li><li><strong>Delta</strong>: point at the table root, not its <code>_delta_log</code> folder.</li><li>With a <strong>Bucket</strong> or <strong>Container</strong> set, use a path relative to it, such as <code>orders/metadata/v3.metadata.json</code>.</li><li>With no bucket, use a full URI: <code>s3://…</code> for S3 and S3-compatible, <code>gs://…</code> or <code>gcs://…</code> for Google Cloud Storage, <code>az://…</code> for Azure.</li><li>For local storage, use an absolute path such as <code>/data/orders</code>, or a <code>file:///</code> URI.</li></ul><p>Paths can&#39;t contain <code>*</code>, <code>?</code>, <code>[]</code>, <code>{}</code>, or <code>..</code>.</p><h2 id="look-at-an-earlier-version" tabindex="-1">Look at an earlier version <a class="header-anchor" href="#look-at-an-earlier-version" aria-label="Permalink to &quot;Look at an earlier version&quot;">​</a></h2><ol><li>Open the lakehouse tab.</li><li>Drag the <strong>Time travel</strong> slider above the grid. The label shows the commit&#39;s date and time in your time zone and, for Delta, the operation that made it, such as <code>WRITE</code>.</li><li>Release the slider. The grid reloads the table as it was at that commit.</li><li>To return to the current table, click <strong>Latest</strong>.</li></ol><p>The commit you pick is saved on the tab, so collaborators who open it see the same version. Click <strong>Latest</strong> to clear it for everyone. The rows themselves are not saved: each person&#39;s tab reads the table again when they open it.</p><p>For Iceberg, the newest stop is labeled <strong>Latest in configured metadata</strong>: it&#39;s the newest snapshot in the metadata file you entered, which may be older than the live table. Delta stops are table versions; Iceberg stops are snapshots. The slider lists the 1,000 most recent commits.</p><h2 id="use-the-results-in-a-sheet" tabindex="-1">Use the results in a sheet <a class="header-anchor" href="#use-the-results-in-a-sheet" aria-label="Permalink to &quot;Use the results in a sheet&quot;">​</a></h2><p>The grid is read-only: you can select and copy cells, but not edit, sort, or filter them. To build on the data, copy cells with <code>⌘+C</code> / <code>Ctrl+C</code> and paste them into a sheet tab.</p><p>A formula in another tab can&#39;t read a lakehouse tab. A reference such as <code>=Orders!A1</code> returns an empty value.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A read that hits 10,000 rows shows <code>10000 rows (truncated)</code>, and the grid holds only the first 10,000 rows.</li><li>Each tab reads the one table its connection names. You can&#39;t browse a catalog for other tables.</li><li>To change a connection&#39;s details, create a new connection.</li><li>The slider is unavailable while the history loads, and on read-only views such as a viewer share link.</li><li>If a pinned commit is older than the loaded history, the slider is replaced by a note such as <code>Snapshot 41… · outside loaded history</code>. The tab still reads that commit.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/connect-a-database.html">Connect a database</a> to run SQL against PostgreSQL.</li><li><a href="/docs/developers/self-hosting/optional-features.html">Optional features</a> for the server settings behind local paths and custom endpoints.</li><li><a href="/docs/start/troubleshooting.html#local-lakehouse-paths-are-disabled-on-this-server">Troubleshooting</a> if saving fails with <code>Local lakehouse paths are disabled on this server</code>.</li></ul>',29)])])}const b=t(r,[["render",l]]);export{p as __pageData,b as default};
